# Stage-A-only completion of corpus checks when the fresh legacy extraction became available.
p=AUDIT/'blind_answers_3.jsonl'
rows=[json.loads(x) for x in p.read_text(encoding='utf-8').splitlines()]
legacy='INREV__INREV_DDQ_Fund_of'
lt=norm(pages(legacy)[0][1])
assert not re.search(r'ILPA|ISO.?27001|TMRS|DDQ 2\.0',lt,re.I)
for r in rows:
    if r['id'] in ['XD-15','XD-18','XD-24','DDQ-14']:
        r['notes']+=' Stage A final check: newly available original-derived legacy INREV .doc text searched too; no ILPA, ISO 27001, TMRS or DDQ 2.0 mention. Corpus check now includes all 81 originals.'
        if r['id'] in ['XD-15','XD-18']: r['confidence']='high'
    if r['id']=='DDQ-11':
        r['notes']+=' Stage A final check: readable original-derived legacy INREV .doc reviewed; sections 2–4 likewise cover organisation, staff, strategy, governance, risk, fees, performance and ESG.'
        r['blind_source_file']+=';'+source(legacy).name
        r['evidence'].append(ev(legacy,'Real estate fund of funds/multi-manager risk management and compliance','section 2.6'))
assert len(rows)==40 and len({r['id'] for r in rows})==40
p.write_text(''.join(json.dumps(x,ensure_ascii=False)+'\n' for x in rows),encoding='utf-8')
print('Stage A complete: all 40 blind records saved and validated. No golds read.')
